"use client";
import React from "react";
import { ProjectPreview } from "@thatg33k/seene/preview";
import { sceneModules } from "./catalog";
export function SeeneProjectPreview({ children, enabled, active, ...props }) {
  if (!enabled) return children;
  return <ProjectPreview {...props} projectId="51c0cbfc-ee5f-412b-8fd4-dab34c14dc35" enabled={enabled} active={active} sceneModules={sceneModules}>{children}</ProjectPreview>;
}

